import{_ as t,o,c as a,ag as i}from"./chunks/framework.wGDfT7ie.js";const u=JSON.parse('{"title":"Key concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts.md","filePath":"concepts.md"}'),r={name:"concepts.md"};function n(s,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="key-concepts" tabindex="-1">Key concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key concepts&quot;">​</a></h1><h2 id="proof-gating" tabindex="-1">Proof-gating <a class="header-anchor" href="#proof-gating" aria-label="Permalink to &quot;Proof-gating&quot;">​</a></h2><p><strong>Proof-gating</strong> means: the smart contract only executes an action if a valid proof is provided. The proof attests that the action satisfies your constraints (e.g. max position, allowed protocols). Proofs are verified on-chain via Starknet&#39;s <strong>Integrity</strong> fact registry (SHARP). No proof, no execution — so you get MEV protection and verifiable intent.</p><h2 id="session-keys" tabindex="-1">Session keys <a class="header-anchor" href="#session-keys" aria-label="Permalink to &quot;Session keys&quot;">​</a></h2><p><strong>Session keys</strong> let you delegate limited authority to the agent. You sign once (e.g. &quot;agent can act for the next 24h within these limits&quot;); the agent can then submit proof-gated transactions on your behalf. You don&#39;t sign every trade; the agent is bounded by the constraints you set.</p><h2 id="selective-disclosure" tabindex="-1">Selective disclosure <a class="header-anchor" href="#selective-disclosure" aria-label="Permalink to &quot;Selective disclosure&quot;">​</a></h2><p><strong>Selective disclosure</strong> means proving a <em>statement</em> without revealing the underlying data. zkde.fi supports multiple disclosure types:</p><ul><li><strong>Yield/Balance thresholds</strong> — Prove yield or balance exceeds a value</li><li><strong>Risk compliance</strong> — Prove portfolio risk (VaR, Sharpe, max drawdown) is below limits</li><li><strong>Performance proofs</strong> — Prove APY exceeded threshold over a period</li><li><strong>KYC eligibility</strong> — Prove financial standing for regulatory compliance</li><li><strong>Portfolio aggregation</strong> — Prove total value across protocols without revealing breakdown</li></ul><p>You generate a proof and register it on-chain; auditors or protocols see the statement, not your full history.</p><h2 id="confidential-transfers" tabindex="-1">Confidential transfers <a class="header-anchor" href="#confidential-transfers" aria-label="Permalink to &quot;Confidential transfers&quot;">​</a></h2><p><strong>Confidential transfers</strong> hide amounts and balances on the public ledger. Instead of publishing &quot;Alice sent 100 USDC,&quot; the chain stores a <strong>commitment</strong> (e.g. a hash). Only the holder can spend or disclose. On Starknet Sepolia, zkde.fi uses <strong>Garaga</strong> (Groth16 verifier) for this; on mainnet, the stack can use MIST.cash.</p><h3 id="private-deposits" tabindex="-1">Private deposits <a class="header-anchor" href="#private-deposits" aria-label="Permalink to &quot;Private deposits&quot;">​</a></h3><p>When you make a <strong>private deposit</strong>, the amount is hidden. The contract stores a commitment instead of a public balance. You can later prove properties about your deposit without revealing the exact amount.</p><h3 id="private-withdrawals" tabindex="-1">Private withdrawals <a class="header-anchor" href="#private-withdrawals" aria-label="Permalink to &quot;Private withdrawals&quot;">​</a></h3><p><strong>Private withdrawals</strong> complete the confidential transfer cycle. To withdraw:</p><ol><li><strong>Generate nullifier</strong> — A unique hash derived from your commitment, nonce, and secret. Prevents double-spend.</li><li><strong>Prove ownership</strong> — Prove you own the commitment and have sufficient balance.</li><li><strong>Submit withdrawal</strong> — Contract verifies proof, marks nullifier as used, transfers funds.</li></ol><p>Your withdrawal amount stays hidden. The chain only sees &quot;commitment X was spent via nullifier Y.&quot;</p><h2 id="private-position-aggregation" tabindex="-1">Private position aggregation <a class="header-anchor" href="#private-position-aggregation" aria-label="Permalink to &quot;Private position aggregation&quot;">​</a></h2><p><strong>Private position aggregation</strong> lets you prove your total portfolio value across multiple protocols without revealing:</p><ul><li>Individual protocol amounts</li><li>Asset allocation breakdown</li><li>Trading strategy</li></ul><p>This enables access to protocol tiers or institutional requirements while maintaining full position privacy.</p><p>Next: <a href="/docs/flow.html">How it works</a></p>',22)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
